40	func TestPathSourcePickerNewIsLoadingWithOnlyTheHost(t *testing.T) {
41		p := newPathSourcePicker(hostSource())
42		if len(p.sources) != 1 || !p.sources[0].isHost() {
43			t.Fatalf("sources = %+v, want only this machine", p.sources)
44		}
45		if p.cursor != 0 || !p.loading {
46			t.Errorf("cursor=%d loading=%v, want 0 and true", p.cursor, p.loading)
47		}
48		body := strings.Join(plain(p.render(80, 10)), "\n")
49		if !strings.Contains(body, "this machine (current)") {
50			t.Errorf("render lacks %q:\n%s", "this machine (current)", body)
51		}
52		// Rule 128: loading goes to the footer, never to the body.
53		for _, bad := range []string{"Loading", "Reading", "loading"} {
54			if strings.Contains(body, bad) {
55				t.Errorf("body carries loading text %q:\n%s", bad, body)
56			}
57		}
