60	func TestPathSourcePickerWithList(t *testing.T) {
61		api, web := pickerSrc("api"), pickerSrc("web-1")
62		tests := []struct {
63			name       string
64			current    pathSource
65			list       pathSourceList
66			wantNames  []string
67			wantCursor int
68			wantNote   string
69		}{
70			{"cursor on current container", web, pathSourceList{Containers: []pathSource{api, web}}, []string{"this machine", "api", "web-1"}, 2, ""},
71			{"current vanished falls back to host", pickerSrc("gone"), pathSourceList{Containers: []pathSource{api, web}}, []string{"this machine", "api", "web-1"}, 0, ""},
72			{"host current", hostSource(), pathSourceList{Containers: []pathSource{api}}, []string{"this machine", "api"}, 0, ""},
73			{"only the host plus a note", hostSource(), pathSourceList{Containers: []pathSource{}, Note: noteNoContainer}, []string{"this machine"}, 0, noteNoContainer},
74			{"note without containers keeps current host", web, pathSourceList{Note: noteNoEngine}, []string{"this machine"}, 0, noteNoEngine},
75		}
76		for _, tt := range tests {
77			t.Run(tt.name, func(t *testing.T) {
78				before := newPathSourcePicker(tt.current)
79				got := before.withList(tt.list)
80				if got.loading {
81					t.Error("still loading after withList")
82				}
83				if !before.loading {
84					t.Error("withList mutated its receiver")
85				}
86				var names []string
87				for _, s := range got.sources {
88					names = append(names, s.label())
89				}
90				if strings.Join(names, ",") != strings.Join(tt.wantNames, ",") {
91					t.Errorf("rows = %v, want %v", names, tt.wantNames)
92				}
93				if got.cursor != tt.wantCursor {
94					t.Errorf("cursor = %d, want %d", got.cursor, tt.wantCursor)
95				}
96				if got.note != tt.wantNote {
97					t.Errorf("note = %q, want %q", got.note, tt.wantNote)
98				}
99				if want := tt.wantNames[tt.wantCursor]; got.selected().label() != want {
100					t.Errorf("selected = %q, want %q", got.selected().label(), want)
101				}
102			})
103		}
104	}
105	
106	func TestPathSourcePickerNoteStaysOutOfTheBody(t *testing.T) {
107		p := newPathSourcePicker(hostSource()).withList(pathSourceList{Containers: []pathSource{}, Note: noteNoContainer})
108		body := strings.Join(plain(p.render(80, 10)), "\n")
109		if strings.Contains(body, "No running container") {
110			t.Errorf("the note belongs to the footer (H4), not the body:\n%s", body)
111		}
112		if !strings.Contains(body, "this machine") {
113			t.Errorf("host row missing:\n%s", body)
114		}
115	}
