117	func TestPathSourcePickerMove(t *testing.T) {
118		const rows = 3
119		tests := []struct {
120			name       string
121			n          int // containers; entries = n+1
122			start      int
123			keys       []string
124			wantCursor int
125		}{
126			{"down", 10, 0, []string{"down"}, 1},
127			{"down stays at the end", 2, 2, []string{"down"}, 2},
128			{"up stays at 0", 10, 0, []string{"up"}, 0},
129			{"up", 10, 3, []string{"up"}, 2},
130			{"end", 10, 0, []string{"end"}, 10},
131			{"home", 10, 10, []string{"home"}, 0},
132			{"pgdown by rows", 10, 0, []string{"pgdown"}, rows},
133			{"pgdown clamps", 10, 9, []string{"pgdown"}, 10},
134			{"pgup by rows", 10, 8, []string{"pgup"}, 8 - rows},
135			{"pgup clamps", 10, 1, []string{"pgup"}, 0},
136			{"tab does nothing", 10, 4, []string{"tab"}, 4},
137			{"shift+tab does nothing", 10, 4, []string{"shift+tab"}, 4},
138			{"enter does nothing", 10, 4, []string{"enter"}, 4},
139			{"esc does nothing", 10, 4, []string{"esc"}, 4},
140			{"a letter does nothing", 10, 4, []string{"j", "k", "g", "G"}, 4},
141			{"left and right do nothing", 10, 4, []string{"left", "right"}, 4},
142		}
143		for _, tt := range tests {
144			t.Run(tt.name, func(t *testing.T) {
145				p := pickerWith(tt.n)
146				p.cursor = tt.start
147				// start from a consistent window, as a previous move would leave it
148				if tt.start >= rows {
149					p.top = tt.start - rows + 1
150				}
151				for _, k := range tt.keys {
152					p = p.move(pickerKey(k), rows)
153					if p.cursor < p.top || p.cursor >= p.top+rows {
154						t.Fatalf("after %q cursor %d outside window [%d,%d)", k, p.cursor, p.top, p.top+rows)
155					}
156				}
157				if p.cursor != tt.wantCursor {
158					t.Errorf("cursor = %d, want %d", p.cursor, tt.wantCursor)
159				}
160			})
161		}
162	}
163	
164	func TestPathSourcePickerMoveReturnsANewValue(t *testing.T) {
165		p := pickerWith(5)
166		_ = p.move(pickerKey("down"), 3)
167		if p.cursor != 0 {
168			t.Errorf("move mutated its receiver: cursor = %d", p.cursor)
