172	func TestPathSourcePickerTopFollowsTheCursor(t *testing.T) {
173		p := pickerWith(9) // 10 entries, 3 visible
174		for i := range 9 {
175			p = p.move(pickerKey("down"), 3)
176			if p.cursor != i+1 {
177				t.Fatalf("step %d: cursor = %d, want %d", i, p.cursor, i+1)
178			}
179			if p.cursor < p.top || p.cursor >= p.top+3 {
180				t.Fatalf("step %d: cursor %d outside [%d,%d)", i, p.cursor, p.top, p.top+3)
181			}
182		}
183		for i := range 9 {
184			p = p.move(pickerKey("up"), 3)
185			if p.cursor < p.top || p.cursor >= p.top+3 {
186				t.Fatalf("up step %d: cursor %d outside [%d,%d)", i, p.cursor, p.top, p.top+3)
187			}
188		}
189		if p.cursor != 0 || p.top != 0 {
190			t.Errorf("back at the start: cursor=%d top=%d, want 0 0", p.cursor, p.top)
191		}
192	}
193	
194	func TestPathSourcePickerBoxWidth(t *testing.T) {
195		// H2: clamp(width-4, 20, 60).
196		tests := []struct{ width, want int }{{80, 60}, {200, 60}, {64, 60}, {60, 56}, {30, 26}, {24, 20}, {10, 20}}
197		for _, tt := range tests {
198			if got := pickerBoxWidth(tt.width); got != tt.want {
199				t.Errorf("pickerBoxWidth(%d) = %d, want %d", tt.width, got, tt.want)
200			}
201		}
202	}
203	
204	func TestPathSourcePickerRenderGeometry(t *testing.T) {
205		long := pathSource{ID: strings.Repeat("b", 12) + "long", Name: strings.Repeat("n", 60), Image: strings.Repeat("i", 40)}
206		tests := []struct {
207			name          string
208			width, height int
209			list          pathSourceList
210			current       pathSource
211		}{
212			{"80x10", 80, 10, pathSourceList{Containers: []pathSource{pickerSrc("api"), pickerSrc("web-1")}}, pickerSrc("web-1")},
213			{"60x5 long name", 60, 5, pathSourceList{Containers: []pathSource{long, pickerSrc("z")}}, long},
214			{"24x3", 24, 3, pathSourceList{Containers: []pathSource{long, pickerSrc("z")}}, hostSource()},
215			{"80x10 note only host", 80, 10, pathSourceList{Containers: []pathSource{}, Note: noteNoContainer}, hostSource()},
216		}
217		for _, tt := range tests {
218			t.Run(tt.name, func(t *testing.T) {
219				p := newPathSourcePicker(tt.current).withList(tt.list)
220				lines := p.render(tt.width, tt.height)
221				if len(lines) == 0 {
222					t.Fatal("render returned no line")
223				}
224				wantRows := min(len(p.sources), tt.height-2)
225				if len(lines) != wantRows+2 {
226					t.Errorf("%d lines, want %d rows + 2 borders", len(lines), wantRows)
227				}
228				box := pickerBoxWidth(tt.width)
229				for i, l := range lines {
230					if w := ansi.StringWidth(l); w != box {
231						t.Errorf("line %d width = %d, want %d: %q", i, w, box, ansi.Strip(l))
232					}
233					if strings.ContainsAny(ansi.Strip(l), "\x1b\a") {
234						t.Errorf("line %d keeps a cut or foreign escape: %q", i, l)
235					}
236				}
237				if !strings.Contains(ansi.Strip(lines[0]), "Trace from") {
238					t.Errorf("title missing in the top border: %q", ansi.Strip(lines[0]))
239				}
240			})
241		}
242	}
243	
244	func TestPathSourcePickerRenderMarksTheCursorRow(t *testing.T) {
245		p := newPathSourcePicker(pickerSrc("web-1")).withList(pathSourceList{Containers: []pathSource{pickerSrc("api"), pickerSrc("web-1")}})
246		lines := plain(p.render(80, 10))
247		if len(lines) != 5 {
248			t.Fatalf("%d lines, want 3 rows + 2 borders", len(lines))
249		}
250		body := lines[1 : len(lines)-1]
251		for i, l := range body {
252			hasMark := strings.Contains(l, theme.IconCircleSmall+" ")
253			if want := i == 2; hasMark != want {
254				t.Errorf("row %d mark = %v, want %v: %q", i, hasMark, want, l)
255			}
256			if i != 2 && !strings.Contains(l, "  ") {
257				t.Errorf("row %d lacks the two-space prefix: %q", i, l)
258			}
259		}
260		if !strings.Contains(body[2], "web-1 (current)") {
261			t.Errorf("current source not marked: %q", body[2])
262		}
263		if strings.Contains(body[1], "(current)") || strings.Contains(body[0], "(current)") {
264			t.Errorf("(current) on the wrong row: %q / %q", body[0], body[1])
265		}
266		if !strings.Contains(body[1], "api") || !strings.Contains(body[1], "img/api") {
267			t.Errorf("row lacks name and image: %q", body[1])
268		}
269	}
270	
271	func TestPathSourcePickerRenderTruncatesLongNames(t *testing.T) {
272		long := pathSource{ID: strings.Repeat("c", 16), Name: strings.Repeat("n", 60), Image: "img"}
273		p := newPathSourcePicker(hostSource()).withList(pathSourceList{Containers: []pathSource{long}})
274		body := strings.Join(plain(p.render(60, 6)), "\n")
275		if !strings.Contains(body, "…") {
276			t.Errorf("no truncation mark for a 60-rune name in a %d-cell box:\n%s", pickerBoxWidth(60), body)
277		}
278		if strings.Contains(body, strings.Repeat("n", 60)) {
279			t.Errorf("the long name was not cut:\n%s", body)
280		}
281	}
282	
283	func TestPathSourcePickerRenderNeverLeaksAnEngineEscape(t *testing.T) {
284		list := sourceListFrom("docker", "Ubuntu", nil, []docker.Container{
285			{ID: strings.Repeat("d", 64), Name: "x\x1b]0;pwn\ay", Image: "i\x1b[31mmg", State: "running"},
286		}, nil)
287		if len(list.Containers) != 1 {
288			t.Fatalf("fixture: %d containers, want 1", len(list.Containers))
289		}
290		p := newPathSourcePicker(hostSource()).withList(list)
291		lines := p.render(80, 10)
292		if len(lines) != 4 {
293			t.Fatalf("%d lines, want 2 rows + 2 borders", len(lines))
294		}
295		for _, l := range lines {
296			if s := ansi.Strip(l); strings.Contains(s, "]0;") || strings.ContainsAny(s, "\x1b\a") {
297				t.Errorf("escape payload leaked: %q", s)
298			}
299			if strings.Contains(l, "\x1b]0;") {
300				t.Errorf("raw OSC in the rendered line: %q", l)
301			}
302		}
303	}
304	
305	func TestPathSourcePickerRenderIsPure(t *testing.T) {
306		p := pickerWith(6).move(pickerKey("end"), 3)
307		a := p.render(80, 6)
308		b := p.render(80, 6)
309		if strings.Join(a, "\n") != strings.Join(b, "\n") {
310			t.Error("two renders of the same value differ")
311		}
312	}
