func TestScratchResizeGrow(t *testing.T) {
	p := pickerWith(9).move("end", 3)
	lines := p.render(80, 12)
	t.Logf("top=%d cursor=%d lines=%d (want 12)", p.top, p.cursor, len(lines))
	for _, l := range plain(lines) { t.Log(l) }
	if len(lines) != 12 { t.Errorf("lines=%d want 12", len(lines)) }
}

func TestScratchWide(t *testing.T) {
	cjk := pathSource{ID: strings.Repeat("e", 12) + "x", Name: strings.Repeat("日本語", 15), Image: "イメージ/名前"}
	cjk2 := pathSource{ID: strings.Repeat("f", 12) + "y", Name: "名前" , Image: "img"}
	for _, w := range []int{80, 60, 24} {
		for _, cur := range []pathSource{cjk, cjk2, hostSource()} {
			p := newPathSourcePicker(cur).withList(pathSourceList{Containers: []pathSource{cjk, cjk2}})
