	p := newPathSourcePicker(cjk).withList(pathSourceList{Containers: []pathSource{cjk}})
	for _, l := range plain(p.render(80, 6)) { t.Log(l) }
	p = newPathSourcePicker(cjk).withList(pathSourceList{Containers: []pathSource{cjk}})
	for _, l := range plain(p.render(24, 6)) { t.Log(l) }
}
EOF
